import{_ as r,o,c as s,an as a}from"./chunks/framework.Bo8sjaO0.js";const g=JSON.parse('{"title":"Release process","description":"","frontmatter":{},"headers":[],"relativePath":"developer/release-process.md","filePath":"developer/release-process.md","lastUpdated":null}'),t={name:"developer/release-process.md"};function i(n,e,l,c,d,p){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="release-process" tabindex="-1">Release process <a class="header-anchor" href="#release-process" aria-label="Permalink to &quot;Release process {#release-process}&quot;">​</a></h1><p>Releases follow semantic versioning and are driven by the shared EpiAwarePackageTools workflows.</p><h2 id="Versions" tabindex="-1">Versions <a class="header-anchor" href="#Versions" aria-label="Permalink to &quot;Versions {#Versions}&quot;">​</a></h2><ul><li><p><strong>Patch</strong>: bug fixes and performance improvements.</p></li><li><p><strong>Minor</strong>: new operators, modifiers, couplings or keywords that keep existing calls working.</p></li><li><p><strong>Major</strong>: changes to an existing call or a removed public name.</p></li></ul><p><code>auto-version-increment.yaml</code> opens a pull request bumping the patch version after each merge to <code>main</code> that did not change the version. A <code>/version major|minor|patch</code> comment on a pull request, from someone with write access, commits that increment to its branch instead.</p><h2 id="Registration" tabindex="-1">Registration <a class="header-anchor" href="#Registration" aria-label="Permalink to &quot;Registration {#Registration}&quot;">​</a></h2><p>Comment <code>/register</code> on any issue or pull request, or run <strong>Actions → Register → Run workflow</strong>. <code>Register.yml</code> then asks JuliaRegistrator to register <code>main</code>&#39;s head in the General registry. Once the registry pull request merges, TagBot creates the GitHub release and its notes, and the docs deploy for the new version.</p><h2 id="Before-registering" tabindex="-1">Before registering <a class="header-anchor" href="#Before-registering" aria-label="Permalink to &quot;Before registering {#Before-registering}&quot;">​</a></h2><ul><li><p>All CI passes, including the AD and documentation builds.</p></li><li><p>New public names have docstrings, tests and a place in the documentation.</p></li><li><p>The docs environment does not pin EpiAwarePackageTools to its <code>main</code> branch.</p></li></ul>',9)])])}const m=r(t,[["render",i]]);export{g as __pageData,m as default};
